void VaapiVideoDecodeAccelerator::Cleanup() {
  // Ensure the current thread belongs to the task runner
  DCHECK(task_runner_->BelongsToCurrentThread());

  // Lock the mutex using AutoLock
  base::AutoLock auto_lock(lock_);

  // Check if the state is uninitialized or destroying
  if (state_ == kUninitialized || state_ == kDestroying)
    return;

  // Log destruction message
  VLOGF(2) << "Destroying VAVDA";

  // Set state to destroying
  state_ = kDestroying;

  // Reset client pointer factory
  client_ptr_factory_.reset();

  // Invalidate weak pointers
  weak_this_factory_.InvalidateWeakPtrs();

  // Signal input ready condition
  input_ready_.Signal();

  // Signal surfaces available condition
  surfaces_available_.Signal();

  // Stop the decoder thread
  {
    base::AutoUnlock auto_unlock(lock_);
    decoder_thread_.Stop();
  }

  // Set state back to uninitialized
  state_ = kUninitialized;
}
